CREATE TABLE ITP (
    ITEMN INT,
    PONUM INT
);
CREATE TABLE ITM (
    ITEMN INT,
    TYPE INT,
    PRIMARY KEY (ITEMN)
);
CREATE TABLE PUR (
    PONUM INT,
    ODATE INT,
    VENDN INT
);

counterexample:
-- There is no counterexample, because Q1 and Q2 are equivalent on all databases that satisfy the schema.
-- For example, one valid test database (which yields the same result for both queries) is illustrated by the following INSERTs:

INSERT INTO ITM (ITEMN, TYPE) VALUES (10, 1);

INSERT INTO ITP (ITEMN, PONUM) VALUES (10, 1);

INSERT INTO PUR (PONUM, ODATE, VENDN) VALUES (1, 90, 200);

-- When executing Q1 and Q2 over these rows, both return the result (10,200).
-- Thus, no test data can be found where the two queries yield different results.

