);

counterexample:
-- There is no set of INSERT statements that distinguishes Q1 and Q2 under the declared schema.
-- Both queries return the same results. For example, the following test data illustrates equivalent outputs:

INSERT INTO ITP (ITEMNO, NP) VALUES (1, 2000);
INSERT INTO ITP (ITEMNO, NP) VALUES (2, 1500);

INSERT INTO ITM (ITEMNO, TYPE) VALUES (1, 101);
INSERT INTO ITM (ITEMNO, TYPE) VALUES (2, 102);

-- In this test data, both Q1 and Q2 return:
-- Row 1: NP = 2000, TYPE = 101, ITEMNO = 1
-- Row 2: NP = 1500, TYPE = 102, ITEMNO = 2

-- Even if duplicate rows are added to ITP (e.g.: duplicate (1,2000)), the inner DISTINCT in Q1 and the outer DISTINCT in Q2 ensure the result sets remain the same.
-- Thus, given the schema constraints, there is no counterexample where Q1 and Q2 produce different results.

schema:
CREATE TABLE ITP (
    ITEMNO INT,
    NP INT
);
CREATE TABLE ITM (
    ITEMNO INT,
    TYPE INT,
    PRIMARY KEY (ITEMNO)
);

counterexample:
-- There is no counterexample because Q1 and Q2 are equivalent under the provided schema.
-- For example, consider the following test data. Both queries yield the same output.

INSERT INTO ITM (ITEMNO, TYPE) VALUES (1, 10);
INSERT INTO ITM (ITEMNO, TYPE) VALUES (2, 20);

INSERT INTO ITP (ITEMNO, NP) VALUES (1, 100);
INSERT INTO ITP (ITEMNO, NP) VALUES (1, 100);  -- duplicate row
INSERT INTO ITP (ITEMNO, NP) VALUES (2, 200);

-- Q1:
-- SELECT ITM.ITEMNO, ITEMPRICE.NP
-- FROM (SELECT DISTINCT ITP.ITEMNO AS ITN, ITP.NP AS NP FROM ITP) ITEMPRICE, ITM
-- WHERE ITEMPRICE.ITN = ITM.ITEMNO;

-- Q2:
-- SELECT DISTINCT ITM.ITEMNO, ITP.NP
-- FROM ITP, ITM
-- WHERE ITP.ITEMNO = ITM.ITEMNO;

-- Both queries return:
--   ITEMNO | NP
--   1      | 100
--   2      | 200

