schema:
CREATE TABLE R1 (X INT);
CREATE TABLE R2 (X INT);
CREATE TABLE R3 (X INT);

counterexample:
-- No counterexample exists because the queries are equivalent.
-- For example, even with the following test data, Q1 and Q2 return the same results:

INSERT INTO R1 VALUES (1), (2);
INSERT INTO R2 VALUES (10), (20), (10);
INSERT INTO R3 VALUES (30), (40);

-- Q1 computes: SELECT * FROM R1 CROSS JOIN (SELECT * FROM R2 UNION ALL SELECT * FROM R3)
-- Q2 computes: (SELECT * FROM R1 CROSS JOIN R2) UNION ALL (SELECT * FROM R1 CROSS JOIN R3)
-- In both cases, the result is the same multiset of 2*(3+2)=10 rows.

INSERT INTO R1 VALUES (1, 10);
INSERT INTO R1 VALUES (2, 10);
INSERT INTO R2 VALUES (1, 20);

