counterexample:
-- Insert carriers having the same NAME but different CIDs
INSERT INTO CARRIERS (CID, NAME) VALUES (1, 1);
INSERT INTO CARRIERS (CID, NAME) VALUES (2, 1);

-- Insert 500 flights for Carrier 1 for the same day (year 2000, month 1, day 1).
-- Using PostgreSQL's generate_series function for brevity.
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID)
SELECT gs, 2000, 1, 1, 1
FROM generate_series(1,500) AS gs;

-- Insert 501 flights for Carrier 2 for the same day (year 2000, month 1, day 1).
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID)
SELECT gs + 500, 2000, 1, 1, 2
FROM generate_series(1,501) AS gs;

